import{_ as s,H as o,o as t,c as n,aO as d,q as i,s as a,a as l,l as c,aU as p}from"./chunks/framework.vjUPZZJn.js";const R=JSON.parse('{"title":"ROS2 与 DDS 互操作：wire 层约定与跨实现限制","description":"","frontmatter":{"date":"2026-10-13T21:00:00.000Z","title":"ROS2 与 DDS 互操作：wire 层约定与跨实现限制","source":[["1-知识/中间件/DDS/ROS2与DDS互操作深度解析"]],"tags":["机器人","学习笔记","ROS2","DDS"],"categories":["机器人"],"permalink":"/pages/a08627"},"headers":[],"relativePath":"机器人/ROS2 与 DDS 互操作：wire 层约定与跨实现限制.md","filePath":"机器人/ROS2 与 DDS 互操作：wire 层约定与跨实现限制.md","lastUpdated":1791878622000}'),D={name:"机器人/ROS2 与 DDS 互操作：wire 层约定与跨实现限制.md"};function h(_,e,g,u,S,b){const r=o("Mermaid");return t(),n("div",null,[e[2]||(e[2]=d('<h1 id="ros2-与-dds-互操作-wire-层约定与跨实现限制" tabindex="-1">ROS2 与 DDS 互操作：wire 层约定与跨实现限制 <a class="header-anchor" href="#ros2-与-dds-互操作-wire-层约定与跨实现限制" aria-label="Permalink to &quot;ROS2 与 DDS 互操作：wire 层约定与跨实现限制&quot;">​</a></h1> <p>ROS2 的通信后端是 DDS，但「都用了 DDS」不等于天然互通。一个用原生 DDS API 写的节点（比如自研中间件、跨系统桥接程序）要与 ROS2 节点互相收发数据，必须在 wire 层逐项对齐 ROS2 的约定。本文整理这些约定的原理与对齐清单：序列化发生在哪一层、topic 与类型名的变换规则、跨 DDS 实现互通的根本限制、Service wire 帧的头部注入，以及 QoS 静默失配的排查思路。适合做中间件适配、跨系统集成或排查「端点都在却收不到数据」问题的读者。ROS2 内部的序列化管线细节（rosidl 代码生成、CDR 编码规则）另见<a href="./ROS2 消息序列化：从 .msg 到 CDR 字节流.html">本站《ROS2 消息序列化：从 .msg 到 CDR 字节流》</a>，本文聚焦「外部节点如何对上」。</p> <h2 id="ros2-的序列化架构-dds-只是管道" tabindex="-1">ROS2 的序列化架构：DDS 只是管道 <a class="header-anchor" href="#ros2-的序列化架构-dds-只是管道" aria-label="Permalink to &quot;ROS2 的序列化架构：DDS 只是管道&quot;">​</a></h2> <p>先建立一个关键认知：<strong>ROS2 没有使用 DDS 自带的序列化机制</strong>。序列化发生在 typesupport 层，由 rosidl 工具链生成，DDS 被降级为透明传输管道，只搬运 CDR 字节流，不参与编解码。</p> ',8)),(t(),i(p,null,{default:a(()=>[c(r,{id:"mermaid-12",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5B%22.msg%2F.srv%2F.action%22%5D%20--%3E%7Crosidl%20%E5%B7%A5%E5%85%B7%E9%93%BE%7C%20B%5B%22typesupport%20%E4%BB%A3%E7%A0%81%3Cbr%2F%3ECDR%20%E5%BA%8F%E5%88%97%E5%8C%96%E5%87%BD%E6%95%B0%22%5D%0A%20%20%20%20A%20--%3E%7Crosidl%20%E5%B7%A5%E5%85%B7%E9%93%BE%7C%20C%5B%22DDS%20IDL%20*.idl%22%5D%0A%20%20%20%20B%20--%3E%20D%5B%22CDR%20%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%0A%20%20%20%20C%20--%3E%20E%5B%22DDS%20%E7%B1%BB%E5%9E%8B%E6%B3%A8%E5%86%8C%22%5D%0A%20%20%20%20D%20--%3E%20F%5B%22DDS%20impl%EF%BC%88%E4%BC%A0%E8%BE%93%E7%AE%A1%E9%81%93%EF%BC%89%22%5D%0A%20%20%20%20E%20--%3E%20F%0A%20%20%20%20F%20--%3E%20G%5B%22%E7%BD%91%E7%BB%9C%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(`
          Loading...
        `,-1)])]),_:1})),e[3]||(e[3]=d(`<p>每种 DDS 后端对应一种 typesupport 策略：FastDDS 与 Connext 为每个消息类型生成专用序列化代码；CycloneDDS 走内省（introspection）路线，只生成字段元数据，运行时由通用函数遍历编解码。两种策略的对比展开在序列化一文中，这里只需要结论：</p> <p><strong>不同 rmw 实现的 ROS2 节点之间能互通，是因为 typesupport 层统一了 wire 约定——type name 映射、CDR 编码细节、消息头格式都一致。绕过 typesupport 直接用 DDS 原生 API 的节点，只能与 wire 约定逐项一致的对端互通。</strong></p> <h2 id="wire-层命名规则" tabindex="-1">wire 层命名规则 <a class="header-anchor" href="#wire-层命名规则" aria-label="Permalink to &quot;wire 层命名规则&quot;">​</a></h2> <p>与 ROS2 互通的节点要遵守 <code>rmw_cyclonedds_cpp</code> 的命名约定，分 topic 前缀和类型名两部分。</p> <h3 id="topic-命名前缀" tabindex="-1">Topic 命名前缀 <a class="header-anchor" href="#topic-命名前缀" aria-label="Permalink to &quot;Topic 命名前缀&quot;">​</a></h3> <table tabindex="0"><thead><tr><th>通信模式</th> <th>前缀</th> <th>示例</th></tr></thead> <tbody><tr><td>Topic</td> <td><code>rt/</code></td> <td><code>rt/fibonacci/_action/feedback</code></td></tr> <tr><td>Service request</td> <td><code>rq/</code></td> <td><code>rq/fibonacci/_action/send_goalRequest</code></td></tr> <tr><td>Service response</td> <td><code>rr/</code></td> <td><code>rr/fibonacci/_action/send_goalReply</code></td></tr></tbody></table> <p>前缀无尾斜杠，直接拼在话题名前。<code>rmw_cyclonedds</code> 内部用 <code>make_fqtopic()</code> 做这个拼接（源码位于 <code>rmw_cyclonedds_cpp/src/rmw_node.cpp</code>）；原生 DDS 节点要么自己拼前缀，要么在封装层统一处理。</p> <h3 id="类型名变换-rosidl-dds-规则" tabindex="-1">类型名变换（rosidl_dds 规则） <a class="header-anchor" href="#类型名变换-rosidl-dds-规则" aria-label="Permalink to &quot;类型名变换（rosidl_dds 规则）&quot;">​</a></h3> <p><code>rosidl_generator_dds_idl</code> 消费解析后的 IDL（不是原始 <code>.msg</code>），输出带尾下划线的 <code>{MessageName}_.idl</code>。三个结构性变换：</p> <ol><li><strong><code>module dds_</code> 包装</strong>：struct 嵌套在额外的 <code>module dds_ { }</code> 中</li> <li><strong>struct 名尾下划线</strong>：<code>Test</code> → <code>Test_</code></li> <li><strong>成员名尾下划线</strong>：<code>bool_value</code> → <code>bool_value_</code></li></ol> <div class="language-idl vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">idl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module test_msgs {</span></span>
<span class="line"><span>module msg {</span></span>
<span class="line"><span>module dds_ {</span></span>
<span class="line"><span>struct Test_ {</span></span>
<span class="line"><span>    boolean bool_value_;</span></span>
<span class="line"><span>    octet   byte_value_;</span></span>
<span class="line"><span>    long    int32_value_;</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>};</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>类型名公式：<code>::&#39;.join(namespaces + [&#39;dds_&#39;, name + &#39;_&#39;])</code>。例如 <code>std_msgs/msg/Header</code> 对应 wire 层类型名 <code>std_msgs::msg::dds_::Header_</code>。</p> <h3 id="基本类型映射" tabindex="-1">基本类型映射 <a class="header-anchor" href="#基本类型映射" aria-label="Permalink to &quot;基本类型映射&quot;">​</a></h3> <table tabindex="0"><thead><tr><th>ROS 类型</th> <th>DDS IDL</th> <th>备注</th></tr></thead> <tbody><tr><td><code>int8</code> / <code>uint8</code></td> <td><code>octet</code></td> <td>DDS 无 signed byte，<strong>符号信息在 IDL 层丢失</strong></td></tr> <tr><td><code>int16</code> / <code>uint16</code></td> <td><code>short</code> / <code>unsigned short</code></td> <td></td></tr> <tr><td><code>int32</code> / <code>uint32</code></td> <td><code>long</code> / <code>unsigned long</code></td> <td></td></tr> <tr><td><code>int64</code> / <code>uint64</code></td> <td><code>long long</code> / <code>unsigned long long</code></td> <td></td></tr> <tr><td><code>string&lt;=N</code></td> <td><code>string&lt;N&gt;</code></td> <td>有界字符串</td></tr> <tr><td>固定数组</td> <td><code>&lt;type&gt; &lt;name&gt;_[&lt;size&gt;]</code></td> <td></td></tr> <tr><td>有界序列</td> <td><code>sequence&lt;&lt;type&gt;, &lt;max&gt;&gt; &lt;name&gt;_</code></td> <td></td></tr></tbody></table> <p>接口规模的展开也值得注意：一个 Message 对应一个 struct；一个 Service 拆成 request 与 response 两个；一个 Action 展开为七个接口——Goal、Result、Feedback 三个消息，send_goal、cancel_goal、get_result 三个服务，再加一个内层 FeedbackMessage。</p> <h2 id="跨-dds-互通的根本限制" tabindex="-1">跨 DDS 互通的根本限制 <a class="header-anchor" href="#跨-dds-互通的根本限制" aria-label="Permalink to &quot;跨 DDS 互通的根本限制&quot;">​</a></h2> <p>DDS 实现之间理论上可以互通（都遵循 CDR/RTPS 标准），但前提是<strong>双方对 wire 层的所有约定完全一致</strong>。实际障碍主要有三个：</p> <ol><li><strong>type name</strong>：端点发现时靠它匹配，不同 DDS 实现从同一份 IDL 生成的 type name 可能不同</li> <li><strong>CDR 封装细节</strong>：string、sequence 等类型的对齐和编码方式</li> <li><strong>TypeInformation 编码</strong>：DDS-XTypes 1.3 规定 TypeObject 用 XCDR2（PL_CDR2）编码，较早的实现使用 CDR1——解析方按错误格式读取类型信息，轻则匹配失败，重则直接异常</li></ol> <table tabindex="0"><thead><tr><th>互通场景</th> <th>是否可行</th></tr></thead> <tbody><tr><td>原生节点 ↔ 原生节点（同一 DDS 后端）</td> <td>是</td></tr> <tr><td>原生节点 ↔ ROS2 <code>rmw_cyclonedds_cpp</code></td> <td>是（对齐上述约定后）</td></tr> <tr><td>原生节点 ↔ ROS2 <code>rmw_fastrtps_cpp</code></td> <td>通常不可行（TypeInformation 编码冲突，加上 typesupport 约定的差异）</td></tr> <tr><td>原生节点 ↔ 其他 DDS 实现的原生节点</td> <td>取决于 wire 约定是否逐项一致</td></tr></tbody></table> <p>这也是很多团队在引入 ROS2 互通时统一 DDS 实现的原因：多实现互通意味着自行对齐全部 wire 约定并跟踪各实现的版本差异，通常成本高于收益。</p> <h2 id="service-头部注入-header-guid-header-seq" tabindex="-1">Service 头部注入（header_guid / header_seq） <a class="header-anchor" href="#service-头部注入-header-guid-header-seq" aria-label="Permalink to &quot;Service 头部注入（header_guid / header_seq）&quot;">​</a></h2> <p>ROS2 Service 的 wire 帧在 CDR payload 前有一段额外头部，由 <code>rmw_cyclonedds</code> 的序列化器直接写入，<strong>不做字节对齐</strong>：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[RTPS header 4B][guid 8B][seq 8B][IDL payload...]</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>guid</code>：DataWriter 的 <code>dds_instance_handle_t</code>（uint64_t）</li> <li><code>seq</code>：全局递增的 int64_t</li> <li>IDL struct 本身<strong>不含</strong>这些字段，它们是序列化器额外 prepend 的</li></ul> <p>原生 DDS 实现要模拟这个 wire 格式，需要把头部当作 IDL 的前两个字段（<code>header_guid</code> + <code>header_seq</code>），并保证 CDR 字节布局与序列化器的无对齐写入一致。注意 idlcxx（CycloneDDS 的 IDL 编译器）对 <code>uint64</code> 会插入 8 字节对齐 padding，若与无对齐写入错位会反序列化失败——特定版本组合下 padding 影响可能恰好被吸收，但这是脆弱点，升级版本时要重新验证。</p> <h2 id="qos-与容错机制" tabindex="-1">QoS 与容错机制 <a class="header-anchor" href="#qos-与容错机制" aria-label="Permalink to &quot;QoS 与容错机制&quot;">​</a></h2> <h3 id="ros2-的三种容错-qos" tabindex="-1">ROS2 的三种容错 QoS <a class="header-anchor" href="#ros2-的三种容错-qos" aria-label="Permalink to &quot;ROS2 的三种容错 QoS&quot;">​</a></h3> <table tabindex="0"><thead><tr><th>QoS</th> <th>作用</th> <th>触发</th> <th>适用范围</th></tr></thead> <tbody><tr><td>Deadline</td> <td>超时检测</td> <td>期望时间内没收到新数据</td> <td>Topic</td></tr> <tr><td>Liveliness</td> <td>存活检测</td> <td>活跃性断言未在 lease 期内刷新</td> <td>Topic</td></tr> <tr><td>Lifespan</td> <td>数据过期</td> <td>数据存活超过设定时长被丢弃</td> <td>Topic</td></tr></tbody></table> <p><strong>关键限制</strong>：ROS2 的 Service 和 Action API 未暴露 Deadline/Liveliness 这类容错 QoS——它们只在 Topic 上可用。Service server 感知不到 client 的异常退出，Action 对端死亡时也不会触发回调（相关讨论见 <a href="https://github.com/ros2/rclcpp/issues/2241" target="_blank" rel="noreferrer">ros2/rclcpp#2241</a>，&quot;No callbacks if client/server died&quot;，截至目前仍然 open）。该 issue 报告者的做法是补一条心跳 Topic 并配 Deadline QoS 检测对端存活，这也是社区通行的补偿模式。CycloneDDS 提供 WaitSet + StatusCondition + Listener 三种方式监听 QoS 违规，无需轮询。</p> <h3 id="qos-兼容性是静默失败陷阱" tabindex="-1">QoS 兼容性是静默失败陷阱 <a class="header-anchor" href="#qos-兼容性是静默失败陷阱" aria-label="Permalink to &quot;QoS 兼容性是静默失败陷阱&quot;">​</a></h3> <p>DDS 端点匹配时，<strong>reader 要求的可靠性不能高于 writer 提供的</strong>。例如 RELIABLE reader 订阅 BEST_EFFORT writer，QoS 不兼容，DDS 会静默拒绝匹配——不报错，只是 matched 计数为 0。这类问题排查起来很困难，表现为「端点都在但收不到数据」「wait_for_server 超时」。Action 各通道的 QoS 也必须逐项与 ROS2 对齐（feedback 通道是 RELIABLE 而非 BEST_EFFORT，status 通道是 TRANSIENT_LOCAL + depth=1），否则触发同样的静默失配。</p> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li><strong>ROS2 的序列化在 typesupport 层，DDS 只是管道</strong>。绕过 typesupport 的原生 DDS 节点，只能与 wire 约定逐项一致的对端互通。</li> <li><strong>wire 命名三件事</strong>：topic 前缀（<code>rt/</code>、<code>rq/</code>、<code>rr/</code>）、类型名（<code>dds_::Name_</code> 形态）、成员名尾下划线。CycloneDDS 的 XTypes 匹配可能检查 member name，命名不一致会静默不匹配。</li> <li><strong>跨 DDS 互通的前提是 wire 约定逐项一致</strong>：type name、CDR 编码、TypeInformation 编码。XCDR2 与 CDR1 的分歧是 CycloneDDS 与老版本 FastDDS 之间最常见的死结。</li> <li><strong>int8/uint8 都映射 octet</strong>，符号信息在 IDL 层丢失。</li> <li><strong>Service wire 帧的头部（guid + seq）由序列化器 prepend，非对齐写入</strong>；模拟时注意 idlcxx 的对齐 padding 与它错位的风险。</li> <li><strong>QoS 不兼容是静默失败</strong>：RELIABLE reader 撞上 BEST_EFFORT writer 会被 DDS 静默拒绝，永远收不到数据。</li> <li><strong>Service/Action 无原生 Deadline/Liveliness</strong>，通行做法是心跳 Topic 补偿。</li></ul> <h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2> <ul><li><a href="https://design.ros2.org/articles/topic_and_service_names.html" target="_blank" rel="noreferrer">ROS 2 设计文档：Topic and Service name mapping to DDS（rt/rq/rr 前缀的官方出处）</a></li> <li><a href="https://github.com/ros2/rosidl" target="_blank" rel="noreferrer">ros2/rosidl 仓库（rosidl_generator_dds_idl 与类型名变换规则）</a></li> <li><a href="https://github.com/ros2/rmw_cyclonedds" target="_blank" rel="noreferrer">ros2/rmw_cyclonedds（make_fqtopic 与 Service 头部注入的实现）</a></li> <li><a href="https://github.com/ros2/rclcpp/issues/2241" target="_blank" rel="noreferrer">ros2/rclcpp#2241：No callbacks if client/server died</a></li> <li><a href="https://www.omg.org/spec/DDS-XTypes/1.3" target="_blank" rel="noreferrer">OMG DDS-XTypes 1.3 规范（TypeObject 与 XCDR2 编码）</a></li></ul>`,67))])}const E=s(D,[["render",h]]);export{R as __pageData,E as default};
